SET @protocol_id = (SELECT id FROM protocols LIMIT 1);
SET @trial_id = (SELECT trialId FROM protocols LIMIT 1);

-- Create task scaffold
INSERT INTO task_scaffolds (protocolId, trialId, status, createdAt, updatedAt)
VALUES (@protocol_id, @trial_id, 'draft', NOW(), NOW());

SET @scaffold_id = LAST_INSERT_ID();

-- Create sections
INSERT INTO scaffold_sections (scaffoldId, name, description, `order`, color, createdAt, updatedAt) VALUES
(@scaffold_id, 'Screening Phase', 'Patient screening and eligibility assessment', 1, '#3B82F6', NOW(), NOW()),
(@scaffold_id, 'Treatment Phase', 'Active treatment administration and monitoring', 2, '#10B981', NOW(), NOW()),
(@scaffold_id, 'Follow-up Phase', 'Post-treatment monitoring and data collection', 3, '#F59E0B', NOW(), NOW()),
(@scaffold_id, 'Study Closeout', 'Final assessments and study closure activities', 4, '#8B5CF6', NOW(), NOW());

-- Get section IDs
SET @screening_id = (SELECT id FROM scaffold_sections WHERE scaffoldId = @scaffold_id AND name = 'Screening Phase');
SET @treatment_id = (SELECT id FROM scaffold_sections WHERE scaffoldId = @scaffold_id AND name = 'Treatment Phase');
SET @followup_id = (SELECT id FROM scaffold_sections WHERE scaffoldId = @scaffold_id AND name = 'Follow-up Phase');
SET @closeout_id = (SELECT id FROM scaffold_sections WHERE scaffoldId = @scaffold_id AND name = 'Study Closeout');

-- Create tasks for Screening Phase
INSERT INTO scaffold_tasks (scaffoldId, sectionId, name, description, duration, `order`, assignedRole, status, createdAt, updatedAt) VALUES
(@scaffold_id, @screening_id, 'IRB/IEC Approval', 'Obtain Institutional Review Board or Independent Ethics Committee approval', 30, 1, 'Regulatory Affairs', 'pending', NOW(), NOW()),
(@scaffold_id, @screening_id, 'Site Initiation Visit', 'Conduct site initiation visit and training for study staff', 5, 2, 'Clinical Research Associate', 'pending', NOW(), NOW()),
(@scaffold_id, @screening_id, 'Patient Recruitment', 'Recruit and screen potential study participants', 60, 3, 'Study Coordinator', 'pending', NOW(), NOW()),
(@scaffold_id, @screening_id, 'Informed Consent', 'Obtain informed consent from eligible participants', 1, 4, 'Principal Investigator', 'pending', NOW(), NOW()),
(@scaffold_id, @screening_id, 'Baseline Assessments', 'Complete baseline clinical assessments and laboratory tests', 7, 5, 'Study Nurse', 'pending', NOW(), NOW());

-- Create tasks for Treatment Phase
INSERT INTO scaffold_tasks (scaffoldId, sectionId, name, description, duration, `order`, assignedRole, status, createdAt, updatedAt) VALUES
(@scaffold_id, @treatment_id, 'Randomization', 'Randomize participants to treatment arms', 1, 1, 'Study Coordinator', 'pending', NOW(), NOW()),
(@scaffold_id, @treatment_id, 'Drug Dispensing', 'Dispense investigational product to participants', 1, 2, 'Pharmacist', 'pending', NOW(), NOW()),
(@scaffold_id, @treatment_id, 'Treatment Administration', 'Administer treatment according to protocol schedule', 84, 3, 'Study Nurse', 'pending', NOW(), NOW()),
(@scaffold_id, @treatment_id, 'Safety Monitoring', 'Monitor and document adverse events and safety parameters', 84, 4, 'Principal Investigator', 'pending', NOW(), NOW()),
(@scaffold_id, @treatment_id, 'Efficacy Assessments', 'Conduct scheduled efficacy assessments and measurements', 84, 5, 'Study Coordinator', 'pending', NOW(), NOW());

-- Create tasks for Follow-up Phase
INSERT INTO scaffold_tasks (scaffoldId, sectionId, name, description, duration, `order`, assignedRole, status, createdAt, updatedAt) VALUES
(@scaffold_id, @followup_id, 'End of Treatment Visit', 'Complete end of treatment assessments', 1, 1, 'Principal Investigator', 'pending', NOW(), NOW()),
(@scaffold_id, @followup_id, 'Follow-up Visits', 'Conduct scheduled follow-up visits', 90, 2, 'Study Coordinator', 'pending', NOW(), NOW()),
(@scaffold_id, @followup_id, 'Long-term Safety Monitoring', 'Monitor long-term safety and collect adverse event data', 90, 3, 'Study Nurse', 'pending', NOW(), NOW());

-- Create tasks for Study Closeout
INSERT INTO scaffold_tasks (scaffoldId, sectionId, name, description, duration, `order`, assignedRole, status, createdAt, updatedAt) VALUES
(@scaffold_id, @closeout_id, 'Data Lock', 'Complete data entry and lock database', 14, 1, 'Data Manager', 'pending', NOW(), NOW()),
(@scaffold_id, @closeout_id, 'Statistical Analysis', 'Perform statistical analysis of study data', 30, 2, 'Biostatistician', 'pending', NOW(), NOW()),
(@scaffold_id, @closeout_id, 'Final Study Report', 'Prepare and submit final clinical study report', 60, 3, 'Medical Writer', 'pending', NOW(), NOW()),
(@scaffold_id, @closeout_id, 'Site Closeout Visit', 'Conduct site closeout visit and archive study documents', 5, 4, 'Clinical Research Associate', 'pending', NOW(), NOW());

SELECT 'Demo data inserted successfully!' as result;

